import { test, expect } from "bun:test";
import { readFileSync } from "fs";
import { join } from "path";
import {
  OP_HTTP_REQUEST,
  bodyText,
  defWeb,
  encodeBody,
  htmlResponse,
  jsonResponse,
  textResponse,
  type Ctx,
  type HTTPRequest,
  type HTTPResponse,
} from "./http";

// Golden fixtures are generated by the Go source of truth
// (internal/wire: `go test -run TestHTTPGolden -update`) and shared by all three SDKs.
const goldenDir = join(import.meta.dir, "../../../testdata/wire/http");
const golden = (name: string) => JSON.parse(readFileSync(join(goldenDir, `${name}.json`), "utf-8"));

// The same logical cases as httpGoldenCases() in internal/wire/http_test.go, built through the typed
// shapes so a renamed or retyped field fails to line up with the fixture. Bodies are the base64 the
// Go []byte marshalled to.
const cases: Record<string, HTTPRequest | HTTPResponse> = {
  req_get: { method: "GET", path: "/" },
  req_post_binary: {
    method: "POST",
    path: "/upload",
    headers: { "Content-Type": ["application/octet-stream"] },
    body: "AAH/EA==",
  },
  req_query_multi: {
    method: "GET",
    path: "/search",
    query: "q=cats&q=dogs&safe=1",
    headers: { Accept: ["text/html"], "X-Tag": ["a", "b"] },
  },
  resp_html: { status: 200, headers: { "Content-Type": ["text/html; charset=utf-8"] }, body: "PGgxPmhpPC9oMT4=" },
  resp_json: { status: 201, headers: { "Content-Type": ["application/json"] }, body: "eyJvayI6dHJ1ZX0=" },
  resp_cookies: { status: 200, headers: { "Set-Cookie": ["a=1", "b=2"] }, body: "b2s=" },
  resp_minimal: { status: 204 },
};

for (const [name, value] of Object.entries(cases)) {
  test(`${name} matches the Go golden fixture`, () => {
    // Compare parsed values (field order and Go's & query escaping are not significant).
    expect(JSON.parse(JSON.stringify(value))).toEqual(golden(name));
  });
}

test("response constructors set status, content type and a base64 body", () => {
  expect(textResponse(200, "hi")).toEqual({
    status: 200,
    headers: { "Content-Type": ["text/plain; charset=utf-8"] },
    body: encodeBody("hi"),
  });
  expect(htmlResponse(404, "<p>gone</p>").headers?.["Content-Type"]?.[0]).toBe("text/html; charset=utf-8");
  const j = jsonResponse(201, { ok: true });
  expect(j.status).toBe(201);
  expect(bodyText(j)).toBe('{"ok":true}');
});

test("bodyText decodes the Go-produced html fixture", () => {
  expect(bodyText(golden("resp_html") as HTTPResponse)).toBe("<h1>hi</h1>");
});

test("defWeb answers http_request with the handler's response and threads state", async () => {
  const def = defWeb<number>({
    name: "web",
    init: () => 0,
    handle: (req, hits) => [htmlResponse(200, `path=${req.path} hits=${hits + 1}`), hits + 1],
  });
  const handler = def.handleCall?.[OP_HTTP_REQUEST];
  expect(handler).toBeDefined();
  const req: HTTPRequest = { method: "GET", path: "/hello" };
  const [resp, next] = await handler!(req, 4, {} as Ctx);
  expect(next).toBe(5);
  expect(bodyText(resp as HTTPResponse)).toBe("path=/hello hits=5");
});

test("defWeb requires a handle", () => {
  // deno-lint-ignore no-explicit-any
  expect(() => defWeb({ name: "x" } as any)).toThrow(/handle is required/);
});
